def prog_name():
    # Usage shows "executable" (basename of argv[0]? Or hardcoded? It's basename of binary name)
    # Our binary will be named "executable", so basename is "executable". Use that.
    # But if invoked via different name, should show that name? Clap uses bin name from argv[0] basename.
    # We'll use os.path.basename(sys.argv[0])
    return os.path.basename(sys.argv[0]) or "executable"

def generic_usage_top():
    return f"Usage: {prog_name()} [OPTIONS] <COMMAND>"

def generic_usage_sub(cmd):
    # Generic usages as observed:
    # compile: "Usage: executable compile [OPTIONS] <INPUT> [OUTPUT]"
    # watch: same
    # init: "Usage: executable init [OPTIONS] <TEMPLATE> [DIR]"
    # eval: "Usage: executable eval [OPTIONS] <EXPRESSION>"
    # fonts: "Usage: executable fonts [OPTIONS]"
    # completions: "Usage: executable completions <SHELL>"
    # info: "Usage: executable info [OPTIONS]"
    # query: "Usage: executable query [OPTIONS] <INPUT> <SELECTOR>"
    # update: "Usage: executable update [OPTIONS] [VERSION]"
    # help: "Usage: executable help [COMMAND]..."
    pn = prog_name()
    if cmd in ("compile","watch"):
        return f"Usage: {pn} {cmd} [OPTIONS] <INPUT> [OUTPUT]"
    elif cmd == "init":
        return f"Usage: {pn} init [OPTIONS] <TEMPLATE> [DIR]"
    elif cmd == "eval":
        return f"Usage: {pn} eval [OPTIONS] <EXPRESSION>"
    elif cmd == "fonts":
        return f"Usage: {pn} fonts [OPTIONS]"
    elif cmd == "completions":
        return f"Usage: {pn} completions <SHELL>"
    elif cmd == "info":
        return f"Usage: {pn} info [OPTIONS]"
    elif cmd == "query":
        return f"Usage: {pn} query [OPTIONS] <INPUT> <SELECTOR>"
    elif cmd == "update":
        return f"Usage: {pn} update [OPTIONS] [VERSION]"
    elif cmd == "help":
        return f"Usage: {pn} help [COMMAND]..."
    else:
        return f"Usage: {pn} {cmd} [OPTIONS]"

def dynamic_usage_missing(cmd, provided_opts, provided_positionals_count=0):
    # For missing required: show provided opts + required positionals
    # provided_opts: list of (long_name, spec) in order of appearance? Or sorted?
    # Observed: "--ppi 100 --format pdf" (order ppi then format) gave "compile --ppi <PPI> --format <FORMAT> <INPUT> [OUTPUT]" (same order as provided)
    # "--format pdf --input a=b --ppi 100" gave "--format <FORMAT> --input <key=value> --ppi <PPI> <INPUT> [OUTPUT]" (same order)
    # So preserve order of first appearance.
    # For flags like --pretty, show "--pretty" (no value)
    # For --open (optional), show "--open [<VIEWER>]" (with brackets)
    # For --timings, show "--timings [<OUTPUT_JSON>]"
    # For --font-path multiple, show once? Observed: "--font-path /tmp --font-path /tmp2" missing gave "--font-path <DIR> <INPUT> [OUTPUT]" (once, not twice). So dedupe.
    # For --input multiple? Probably also once.
    pn = prog_name()
    parts = [pn, cmd]
    seen = set()
    for long_name in provided_opts:
        if long_name in seen:
            continue
        seen.add(long_name)
        spec = OPTS_MAP[cmd].get(long_name)
        if spec is None:
            continue
        if long_name == "help":
            continue
        if not spec["takes_value"]:
            parts.append(f"--{long_name}")
        else:
            if spec.get("optional"):
                # --open [<VIEWER>], --timings [<OUTPUT_JSON>]
                parts.append(f"--{long_name} [<{spec['value_name']}>]")
            else:
                # Need to show as "--format <FORMAT>", "--input <key=value>", etc.
                # For short opts like -f, show long form? Observed: "-f pdf -j 2" missing gave "--format <FORMAT> --jobs <JOBS>" (long forms). So always long.
                parts.append(f"--{long_name} <{spec['value_name']}>")
    # Add positionals based on cmd and provided count?
    # For compile/watch: always "<INPUT> [OUTPUT]"? Or if INPUT provided but OUTPUT missing? But INPUT is required, OUTPUT optional, so missing INPUT means INPUT not provided, show "<INPUT> [OUTPUT]".
